/**
 * Generated by scripts/build-legacy-banner-webp.py.
 * Only exact URLs of legacy images are mapped. Future edits in the admin
 * dashboard use their newly supplied URL, not a stale replacement.
 */
export interface OptimizedLegacyBanner {
  src: string;
  srcSet: string;
}
const sources: Record<string, OptimizedLegacyBanner> = {};
export function getOptimizedLegacyBanner(sourceUrl?: string | null): OptimizedLegacyBanner | undefined {
  if (!sourceUrl) return undefined;
  return sources[sourceUrl];
}
